# Builds js/filamentData.js from the Open Filament Database (MIT).
# usage: python3 -I build_filaments.py <ofd_repo> <out.js> <commit> <date>
import json, glob, os, sys, colorsys
ofd, out, commit, date = sys.argv[1:5]
BRANDS = [('bambu_lab', 'bambu'), ('sunlu', 'sunlu'), ('polymaker', 'polymaker')]

def hue_key(hexes):
    h = hexes[0].lstrip('#')
    r, g, b = (int(h[i:i+2], 16) / 255 for i in (0, 2, 4))
    hh, ll, ss = colorsys.rgb_to_hls(r, g, b)
    if ss < 0.15 or ll < 0.08 or ll > 0.94:   # neutrals first, light to dark
        return (0, -ll, 0)
    return (1, round(hh * 12) % 12, -ll)

brands = []
skipped_disc = 0
for folder, bid in BRANDS:
    bname = json.load(open(f'{ofd}/data/{folder}/brand.json'))['name']
    if bname == 'SUNLU': bname = 'Sunlu'
    lines = []
    base = f'{ofd}/data/{folder}/PLA'
    for line in sorted(os.listdir(base)):
        p = f'{base}/{line}'
        if not os.path.isdir(p): continue
        lname = json.load(open(f'{p}/filament.json'))['name'].replace('™', '')
        colors = []
        for vf in sorted(glob.glob(f'{p}/*/variant.json')):
            v = json.load(open(vf))
            if v.get('discontinued'): skipped_disc += 1; continue
            hx = v['color_hex']
            hexes = [hx] if isinstance(hx, str) else list(hx)
            hexes = [h.lower() for h in hexes]
            colors.append((v['name'].strip(), hexes))
        if not colors: continue
        colors.sort(key=lambda c: hue_key(c[1]))
        lines.append((lname, colors))
    lines.sort(key=lambda l: (-len(l[1]), l[0]))
    brands.append((bid, bname, lines))

def js(s): return json.dumps(s, ensure_ascii=False)
o = []
o.append('// Generated by build_filaments.py from the Open Filament Database\n'
         f'// (https://github.com/OpenFilamentCollective/open-filament-database,\n'
         f'// commit {commit}, {date}): every PLA colour that Bambu Lab, Sunlu and\n'
         '// Polymaker currently sell (discontinued colours left out), grouped by\n'
         '// product line, largest line first, colours ordered by hue. A colour\n'
         '// is [name, hex] or, for multi-colour filaments, [name, [hex, hex, ...]].\n'
         '// The hex values are the database\'s, not measured from spools.\n'
         '//\n'
         '// Open Filament Database: Copyright (c) 2025 OpenFilamentCollective,\n'
         '// MIT License; full text in vendor/open-filament-database/LICENSE.\n'
         '// Regenerate rather than hand-edit.\n\n'
         'export const OFD_BRANDS = [\n')
total = 0
for bid, bname, lines in brands:
    o.append(f'  {{ id: {js(bid)}, name: {js(bname)}, lines: [\n')
    for lname, colors in lines:
        total += len(colors)
        cs = ', '.join(f'[{js(n)}, {js(h[0]) if len(h)==1 else js(h)}]' for n, h in colors)
        o.append(f'    {{ name: {js(lname)}, colors: [{cs}] }},\n')
    o.append('  ] },\n')
o.append('];\n')
open(out, 'w').write(''.join(o))
for bid, bname, lines in brands:
    print(bname, sum(len(c) for _, c in lines), 'colors in', len(lines), 'lines')
print('total', total, 'discontinued skipped', skipped_disc, 'bytes', os.path.getsize(out))
